using System;
using System.Collections.Immutable;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;
using MessagePack.SourceGenerator;
using MessagePack.SourceGenerator.Analyzers;
using Xunit;

public class LedgerIssueClosedGenericValueTypeReferencedAssembly
{
    [Fact]
    public async Task DoesNotCrashAndGeneratesResolver()
    {
        string libSource = """
using MessagePack;

namespace Lib;

[MessagePackObject]
public partial record struct Item<T>([property: Key(0)] string Key);
""";

        string appSource = """
using MessagePack;
using Lib;

namespace App;

[MessagePackObject]
public sealed partial record Cmd([property: Key(0)] string Scope)
{
    [Key(1)] public Item<int> Member { get; init; }
}
""";

        var messagePackRefs = ReferencesHelper.GetReferences(ReferencesSet.MessagePack);
        var frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var baseRefs = messagePackRefs.Concat(frameworkRefs).ToImmutableArray();

        var libTree = CSharpSyntaxTree.ParseText(libSource, new CSharpParseOptions(LanguageVersion.Latest));
        var libCompilation = CSharpCompilation.Create(
            "Lib",
            new[] { libTree },
            baseRefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        using var libStream = new MemoryStream();
        var libEmit = libCompilation.Emit(libStream);
        Assert.True(libEmit.Success, string.Join("\n", libEmit.Diagnostics.Select(d => d.ToString())));
        libStream.Position = 0;
        var libRef = MetadataReference.CreateFromStream(libStream);

        var appTree = CSharpSyntaxTree.ParseText(appSource, new CSharpParseOptions(LanguageVersion.Latest));
        var appRefs = baseRefs.Add(libRef);
        var appCompilation = CSharpCompilation.Create(
            "App",
            new[] { appTree },
            appRefs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var driver = CSharpGeneratorDriver.Create(new MessagePackGenerator().AsSourceGenerator());
        var runResult = driver.RunGeneratorsAndUpdateCompilation(
            appCompilation,
            out var outputCompilation,
            out var generatorDiagnostics).GetRunResult();

        foreach (var result in runResult.Results)
        {
            Assert.True(result.Exception == null, $"Generator threw: {result.Exception}");
        }

        Assert.False(generatorDiagnostics.Any(d => d.Id == "CS8785"), "Generator emitted CS8785");

        var analyzerDiagnostics = await outputCompilation
            .WithAnalyzers(ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer()))
            .GetAnalyzerDiagnosticsAsync();

        Assert.False(analyzerDiagnostics.Any(d => d.Id == "AD0001"), "Analyzer emitted AD0001");

        var resolverHint = runResult.Results
            .SelectMany(r => r.GeneratedSources)
            .FirstOrDefault(s => s.HintName.Contains("Resolver", StringComparison.OrdinalIgnoreCase));
        Assert.NotNull(resolverHint);
    }
}
